pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation)
    // We prioritize perfect fits (post_residual == 0) by subtracting a large constant.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual < 10 {
        score += 40.0;
    }

    // 2. Lookahead Coupling: If next_item_size is large, favor larger post_residuals 
    // to accommodate it, otherwise prefer tighter packing.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0;
        } else {
            score += 30.0;
        }
    }

    // 3. Density Normalization: Balance against the mean residual of the system.
    // If this bin's residual is significantly better than the global mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // 4. Scarcity Constraint: If this is the only bin that fits the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the current 
    // best fit is very poor (e.g., leaving a tiny, unusable sliver).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 25.0; 
        }
        // Scale new bin cost by progress to encourage consolidation late-stream
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 6. Harmonic Class Logic: Use modulo to identify "dead zones" (e.g., residuals 
    // that are unlikely to fit common item sizes).
    let harmonic_mod = post_residual % 25;
    if harmonic_mod < 5 {
        score += 15.0;
    }

    score
}

