    let mut score = post_residual as f64;

    // 1. Adaptive New-Bin Control: Heavily penalize new bins unless no other options exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 250.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 100.0;
        }
    } else {
        // 2. Enhanced Best-Fit logic: prioritize minimizing residual, but scale by remaining capacity.
        // We want to leave space for future items, prioritizing bins that can fit the next item.
        if next_item_size > 0 {
