                score -= 15.0;
                // Reward closer fit to the next item to minimize wasted space.
                score += (post_residual - next_item_size) as f64 * 0.3;
            } else {
                // Penalize bins that create a "dead zone" for the immediate next item.
                score += (next_item_size - post_residual) as f64 * 2.0;
            }
        }
    }

    // 3. Dynamic Thresholding: Use mean_residual to avoid creating bins that deviate significantly
    // from established packing density.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.4;

    // 4. End-of-Stream Compaction: As we approach the end, prioritize tighter packing (post_residual -> 0).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.5);

    // 5. If only one bin fits, prioritize it heavily to avoid opening a new bin unnecessarily.
    // This acts as a guard against the new-bin penalty logic.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

